questionvariables.text:
/* Design backwards. Each context is
   [tag, A, B, C, p, q, fname, ivar, contextintro, varmeaning, quantity, rateunit].
   AROC over [p,q] for f = A x^2 + B x + C is A*(p+q)+B, chosen to be a tidy
   integer. The four families echo the textbook worked examples. The profit family
   uses A=-1 sampled past the vertex, so it supplies the guaranteed negative-rate
   variants. */

/* ---- Car: s(t)=A t^2 km, t hours; average speed (always positive). ---- */
Acar : rand([2,3,4,5]);
pcar : rand([1,2,3]);
qcar : pcar + rand([2,3,4]);
car : [ "car", Acar, 0, 0, pcar, qcar, "s", "t",
        "A car leaves a town. Its distance from the town (in kilometres) after \\(t\\) hours is modelled by",
        "\\(t\\) is the time in hours and \\(s\\) is the distance in kilometres",
        "the distance", "km/h" ];

/* ---- Profit: P(x)=-x^2+bp*x-cp (thousands KSh); sampled past vertex x=bp/2
   so AROC = -(p+q)+bp is negative. ---- */
bp  : rand([30,40,50,60]);
pp0 : bp/2 + rand([2,4,6]);       /* start past the vertex */
qp0 : pp0 + rand([4,6,8]);
cp  : rand([100,200,300,400]);
profit : [ "profit", -1, bp, -cp, pp0, qp0, "P", "x",
        "A small business models its monthly profit (in thousands of KSh) from selling \\(x\\) units as",
        "\\(x\\) is the number of units sold and \\(P\\) is the profit in thousands of KSh",
        "the profit", "thousand KSh per unit" ];

/* ---- Cost: C(x)=x^2-bc*x+dc KSh; sampled past vertex x=bc/2 so AROC>0. ---- */
bc  : rand([4,6,8]);
pc0 : bc/2 + rand([2,4,6]);
qc0 : pc0 + rand([3,5,7]);
dc  : rand([800,1000,1200]);
cost : [ "cost", 1, -bc, dc, pc0, qc0, "C", "x",
        "The cost (in KSh) of producing \\(x\\) bags of maize flour is modelled by",
        "\\(x\\) is the number of bags and \\(C\\) is the cost in KSh",
        "the cost", "KSh per bag" ];

/* ---- Revenue: R(x)=Ar x^2 + br x KSh; AROC = Ar*(p+q)+br > 0. ---- */
Ar  : rand([2,3]);
br  : rand([5,10,15]);
pr0 : rand([5,10]);
qr0 : pr0 + rand([5,10]);
revenue : [ "revenue", Ar, br, 0, pr0, qr0, "R", "x",
        "The revenue (in KSh) generated by selling \\(x\\) items is modelled by",
        "\\(x\\) is the number of items and \\(R\\) is the revenue in KSh",
        "the revenue", "KSh per item" ];

ctx : rand([car, profit, cost, revenue]);

/* unpack */
tag  : ctx[1];
AA   : ctx[2];
BB   : ctx[3];
CC   : ctx[4];
pp   : ctx[5];
qq   : ctx[6];
fname    : ctx[7];
ivar     : ctx[8];
contextintro : ctx[9];
varmeaning   : ctx[10];
quantity     : ctx[11];
rateunit     : ctx[12];

/* the model as a displayed expression in the context variable */
xv  : if is(ivar="t") then t else x;
fexpr : AA*xv^2 + BB*xv + CC;
fdisp : fexpr;

/* function values and the exact AROC (guaranteed integer, nonzero) */
fp  : AA*pp^2 + BB*pp + CC;
fq  : AA*qq^2 + BB*qq + CC;
ta1 : (fq - fp)/(qq - pp);          /* = AA*(pp+qq)+BB */

/* sign interpretation */
increasing_opt : "increasing";
decreasing_opt : "decreasing";
dirword  : if is(ta1>0) then increasing_opt else decreasing_opt;
signword : if is(ta1>0) then "greater than" else "less than";

/* Dropdown model answer: [value, correct?, display]. The stored value is the
   word itself, so the correct value equals dirword and prt2/qtests can compare
   against dirword / increasing_opt / decreasing_opt directly. */
ta2 : [ ["increasing", is(ta1>0), "increasing"],
        ["decreasing", is(ta1<0), "decreasing"] ];

/* a plain-language interpretation sentence for the worked solution */
interpretsentence : if is(tag="car")
   then "The average speed of the car over this interval is positive because it keeps moving away from the town."
   else if is(tag="profit")
   then "Beyond the most profitable output, producing more units lowers profit, so the average rate is negative."
   else if is(tag="cost")
   then "Producing more bags raises total cost, so the average cost per extra bag is positive."
   else "Selling more items raises revenue, so the average revenue per extra item is positive.";

/* wrong-answer variables for misconception diagnostics (must live here, not in
   feedback variables, so the qtests can reference them). */
wrong_divq  : (fq - fp)/qq;         /* divided by q instead of (q-p) */
wrong_sign  : ev(-ta1, simp);       /* sign slip in the numerator */
